INSERT INTO `_robot_talk_copy1` VALUES (35, '졸려]기운없어', '조금 쉬었다 하시죠!]&님, 무리하지 마세요!]커피 한잔 하고 오세요!');
INSERT INTO `_robot_talk_copy1` VALUES (36, '레벨업]렙업했어]레벨 올랐어', '&님, 레벨업 축하드려요!]축하파티 할까요?');
INSERT INTO `_robot_talk_copy1` VALUES (37, '혈맹]혈맹가입]길드모집', '&님 혈맹 가입 환영해요!]길드 분위기 어때요?]혈맹 이벤트 있으신가요?');
INSERT INTO `_robot_talk_copy1` VALUES (38, '물약다씀]물약필요]포션없어', '상점 다녀오실래요?]&님, 물약 같이 사러 가요!]포션 필요하시면 말씀해주세요!');
INSERT INTO `_robot_talk_copy1` VALUES (39, '사냥가자]사냥하러가자]사냥 ㄱ', '지금 사냥 준비됐어요!]물약 충분히 챙기셨나요?');
INSERT INTO `_robot_talk_copy1` VALUES (40, '아이템먹음]템자랑', '오 득템 축하해요!]&님 운 좋으시네요!]어떤 아이템이신가요?]저도 한번 자랑해보고 싶어요!');
INSERT INTO `_robot_talk_copy1` VALUES (41, '안녕]하이]안녕하세요', '오늘 기분은 어떠세요?]다시 만나서 기쁘네요!');
INSERT INTO `_robot_talk_copy1` VALUES (42, '축하]축하해]축하함', '정말 축하해요!]&님 덕분에 즐거워요!]좋은 일 가득하세요!]다 같이 축하해요!');
INSERT INTO `_robot_talk_copy1` VALUES (43, '고마워]감사]땡큐', '감사합니다!]언제나 고마워요!]다음에도 잘 부탁드려요!');
