INSERT INTO `_robot_talk_copy1` VALUES (119, '레벨업]레벨 올림]레벨 올랐어', '&님, 레벨업 축하드려요!]더 강해지셨겠네요!');
INSERT INTO `_robot_talk_copy1` VALUES (120, '거래가능]거래할래', '안전거래로 진행할까요?]&님, 아이템 보여주세요!');
INSERT INTO `_robot_talk_copy1` VALUES (121, '식사했어]밥먹음]점심', '&님, 밥 거르지 마세요!]맛난 거 드시고 힘내세요!');
INSERT INTO `_robot_talk_copy1` VALUES (122, '길드]혈맹가입', '길드 분위기 어때요?]혈맹 이벤트 있으신가요?');
INSERT INTO `_robot_talk_copy1` VALUES (123, '퀘스트]퀘도와줘', '퀘스트 같이 하실래요?]퀘 도움 필요하신가요?');
INSERT INTO `_robot_talk_copy1` VALUES (124, '득템]아이템먹음]템자랑', '오 득템 축하해요!]&님 운 좋으시네요!]저도 한번 자랑해보고 싶어요!');
INSERT INTO `_robot_talk_copy1` VALUES (125, '거래하자]거래가능', '거래창 열었어요!]안전거래로 진행할까요?]&님, 아이템 보여주세요!');
INSERT INTO `_robot_talk_copy1` VALUES (126, '졸려]힘들다]기운없어', '조금 쉬었다 하시죠!]커피 한잔 하고 오세요!');
INSERT INTO `_robot_talk_copy1` VALUES (127, '축하해]축하함', '&님 덕분에 즐거워요!]좋은 일 가득하세요!]다 같이 축하해요!');
INSERT INTO `_robot_talk_copy1` VALUES (128, '밥먹음]점심', '점심 뭐 드셨어요?]맛난 거 드시고 힘내세요!');
INSERT INTO `_robot_talk_copy1` VALUES (129, '기다려]대기]조금만기다려]금방올게', '알겠어요, 천천히 오세요!]&님 기다리고 있을게요!');
INSERT INTO `_robot_talk_copy1` VALUES (130, '물약없어]물약다씀]물약필요]포션없어', '포션 지금 드릴게요!]상점 다녀오실래요?]&님, 물약 같이 사러 가요!');
INSERT INTO `_robot_talk_copy1` VALUES (131, '용던]오만', '어디 던전 가실래요?]파티 모집하고 출발할까요?]&님이 앞장서주세요!]던전 공략 기대됩니다!');
INSERT INTO `_robot_talk_copy1` VALUES (132, '보스]보스잡자]보스레이드', '보스 언제 뜨나요?]보스 잡고 득템하세요!]&님, 레이드 같이 가요!');
INSERT INTO `_robot_talk_copy1` VALUES (133, '힐좀]힐주세요]피없음', '힐 바로 넣을게요!]&님, 피 회복해드릴게요!]조심하세요, 곧 힐 갑니다!');
INSERT INTO `_robot_talk_copy1` VALUES (134, '재접]잠깐나감', '금방 돌아오세요!]재접속 기다릴게요!]&님, 다시 오시면 알려주세요!]문제 없으셨으면 좋겠네요!');
INSERT INTO `_robot_talk_copy1` VALUES (135, '축하]축하드려요', '정말 축하해요!]다 같이 축하해요!');
INSERT INTO `_robot_talk_copy1` VALUES (136, '출석]출첵', '출석 확인했습니다!]&님 출첵 완료!');
INSERT INTO `_robot_talk_copy1` VALUES (137, '기다려]금방올게', '금방 돌아오시길!]&님 기다리고 있을게요!]여기서 대기 중입니다!');
INSERT INTO `_robot_talk_copy1` VALUES (138, '대기]금방올게', '금방 돌아오시길!]여기서 대기 중입니다!');
INSERT INTO `_robot_talk_copy1` VALUES (139, '안녕]하이]방가', '&님도 안녕하세요?]오늘 기분은 어떠세요?]다시 만나서 기쁘네요!');
INSERT INTO `_robot_talk_copy1` VALUES (140, '출석]출석체크]체크인', '출석 확인했습니다!]&님 출첵 완료!]오늘도 접속해주셔서 감사합니다!]좋은 하루 되세요!');
INSERT INTO `_robot_talk_copy1` VALUES (141, '재접]재부팅', '금방 돌아오세요!]&님, 다시 오시면 알려주세요!');
INSERT INTO `_robot_talk_copy1` VALUES (142, '힐좀]힐주세요]피없음]힐필요', '힐 쿨타임 잠깐만요!]조심하세요, 곧 힐 갑니다!');
INSERT INTO `_robot_talk_copy1` VALUES (143, '오만]던전출발', '&님이 앞장서주세요!]던전 공략 기대됩니다!');
INSERT INTO `_robot_talk_copy1` VALUES (144, '뭐해]지금뭐해', '별일 없어요!]&님은 뭐 하세요?]사냥 중이에요!');
INSERT INTO `_robot_talk_copy1` VALUES (145, '거래하자]거래가능]거래할래]아이템거래', '어떤 아이템 거래하시나요?]안전거래로 진행할까요?]&님, 아이템 보여주세요!');
INSERT INTO `_robot_talk_copy1` VALUES (146, '용던]던전가자]던전출발', '파티 모집하고 출발할까요?]&님이 앞장서주세요!]던전 공략 기대됩니다!');
INSERT INTO `_robot_talk_copy1` VALUES (147, '물약없어]물약다씀', '&님, 물약 같이 사러 가요!]포션 필요하시면 말씀해주세요!');
INSERT INTO `_robot_talk_copy1` VALUES (148, '거래하자]거래할래', '어떤 아이템 거래하시나요?]거래창 열었어요!]안전거래로 진행할까요?');
INSERT INTO `_robot_talk_copy1` VALUES (149, '죽었어]죽음]죽다', '어디서 죽으셨어요?]&님, 부활 도와드릴까요?');
INSERT INTO `_robot_talk_copy1` VALUES (150, '혈맹]길드', '혈맹원 구하시나요?]길드 분위기 어때요?');
INSERT INTO `_robot_talk_copy1` VALUES (151, '재접]다시접속]재부팅', '&님, 다시 오시면 알려주세요!]문제 없으셨으면 좋겠네요!');
