INSERT INTO `_robot_talk_copy1` VALUES (153, '퀘스트]퀘진행]퀘스트할래', '퀘스트 같이 하실래요?]퀘 도움 필요하신가요?]퀘 깨면 보상 뭐예요?');
INSERT INTO `_robot_talk_copy1` VALUES (154, '피곤해]힘들다', '조금 쉬었다 하시죠!]체력 관리도 중요해요!');
