INSERT INTO `_robot_talk_copy1` VALUES (156, '축하드려요]축하함', '정말 축하해요!]&님 덕분에 즐거워요!]다 같이 축하해요!');
INSERT INTO `_robot_talk_copy1` VALUES (157, '용던]오만]던전가자', '어디 던전 가실래요?]&님이 앞장서주세요!]던전 공략 기대됩니다!');
INSERT INTO `_robot_talk_copy1` VALUES (158, '사냥가요]사냥 ㄱ', '지금 사냥 준비됐어요!]어느 사냥터 갈까요?]&님 파티 들어오세요!');
