INSERT INTO `_robot_talk_copy1` VALUES (160, '하이]방가', '오늘 기분은 어떠세요?]반가워요!]다시 만나서 기쁘네요!');
INSERT INTO `_robot_talk_copy1` VALUES (161, '거래할래]아이템거래', '어떤 아이템 거래하시나요?]거래창 열었어요!]안전거래로 진행할까요?]&님, 아이템 보여주세요!');
INSERT INTO `_robot_talk_copy1` VALUES (162, '퀘스트]퀘진행]퀘도와줘', '&님, 퀘스트 어디까지 하셨어요?]퀘 도움 필요하신가요?');
INSERT INTO `_robot_talk_copy1` VALUES (163, '축하]축하함', '정말 축하해요!]&님 덕분에 즐거워요!]좋은 일 가득하세요!');
INSERT INTO `_robot_talk_copy1` VALUES (164, '죽었어]죽다', '&님, 부활 도와드릴까요?]다시 힘내봐요!]사망 장소 알려주세요!');
INSERT INTO `_robot_talk_copy1` VALUES (165, 'ㅋㅋ]ㅎㅎ]재밌네]웃겨', '&님 센스 최고!]오늘 기분 최고네요!]같이 웃어요!');
INSERT INTO `_robot_talk_copy1` VALUES (166, '길드]길드모집', '&님 혈맹 가입 환영해요!]혈맹 이벤트 있으신가요?');
INSERT INTO `_robot_talk_copy1` VALUES (167, '죽었어]사망', '&님, 부활 도와드릴까요?]사망 장소 알려주세요!');
INSERT INTO `_robot_talk_copy1` VALUES (168, '힐주세요]피없음', '힐 바로 넣을게요!]&님, 피 회복해드릴게요!]힐 쿨타임 잠깐만요!]조심하세요, 곧 힐 갑니다!');
