INSERT INTO `_robot_talk_copy1` VALUES (175, '축하]축하드려요]축하함', '정말 축하해요!]&님 덕분에 즐거워요!');
INSERT INTO `_robot_talk_copy1` VALUES (176, '재밌네]웃겨', '즐거우셨다니 다행이에요!]오늘 기분 최고네요!');
