INSERT INTO `_robot_talk_copy1` VALUES (179, 'ㅋㅋ]재밌네]웃겨', '즐거우셨다니 다행이에요!]&님 센스 최고!]오늘 기분 최고네요!');
INSERT INTO `_robot_talk_copy1` VALUES (180, '뭐하고있어]뭐함', '&님은 뭐 하세요?]사냥 중이에요!]파티 준비하고 있었어요!');
