INSERT INTO `_robot_talk_copy1` VALUES (202, '밥먹었어]밥먹음', '식사 맛있게 하셨어요?]맛난 거 드시고 힘내세요!');
INSERT INTO `_robot_talk_copy1` VALUES (203, '출석체크]체크인', '출석 확인했습니다!]오늘도 접속해주셔서 감사합니다!');
INSERT INTO `_robot_talk_copy1` VALUES (204, '죽었어]죽음]사망', '어디서 죽으셨어요?]다시 힘내봐요!]사망 장소 알려주세요!');
INSERT INTO `_robot_talk_copy1` VALUES (205, '물약없어]포션없어', '포션 지금 드릴게요!]상점 다녀오실래요?]포션 필요하시면 말씀해주세요!');
INSERT INTO `_robot_talk_copy1` VALUES (206, '보스잡자]보스사냥', '레이드 준비 끝났어요!]&님, 레이드 같이 가요!');
INSERT INTO `_robot_talk_copy1` VALUES (207, '혈맹]혈맹가입', '혈맹원 구하시나요?]&님 혈맹 가입 환영해요!');
INSERT INTO `_robot_talk_copy1` VALUES (208, '안녕]방가', '&님도 안녕하세요?]반가워요!');
INSERT INTO `_robot_talk_copy1` VALUES (209, '뭐해]뭐하고있어]지금뭐해]뭐함', '별일 없어요!]&님은 뭐 하세요?]사냥 중이에요!]파티 준비하고 있었어요!');
INSERT INTO `_robot_talk_copy1` VALUES (210, '피곤해]졸려]힘들다', '&님, 무리하지 마세요!]커피 한잔 하고 오세요!]체력 관리도 중요해요!');
INSERT INTO `_robot_talk_copy1` VALUES (211, '재접]다시접속', '금방 돌아오세요!]재접속 기다릴게요!]&님, 다시 오시면 알려주세요!');
INSERT INTO `_robot_talk_copy1` VALUES (212, '용던]오만]던전출발', '어디 던전 가실래요?]파티 모집하고 출발할까요?');
INSERT INTO `_robot_talk_copy1` VALUES (213, '피곤해]졸려]힘들다]기운없어', '&님, 무리하지 마세요!]체력 관리도 중요해요!');
INSERT INTO `_robot_talk_copy1` VALUES (214, '축하해]축하드려요', '&님 덕분에 즐거워요!]좋은 일 가득하세요!');
INSERT INTO `_robot_talk_copy1` VALUES (215, '죽었어]사망]죽다', '어디서 죽으셨어요?]&님, 부활 도와드릴까요?]다시 힘내봐요!');
INSERT INTO `_robot_talk_copy1` VALUES (216, '축하]축하해]축하드려요', '&님 덕분에 즐거워요!]다 같이 축하해요!');
INSERT INTO `_robot_talk_copy1` VALUES (217, '힐주세요]피없음]힐필요', '힐 바로 넣을게요!]힐 쿨타임 잠깐만요!]조심하세요, 곧 힐 갑니다!');
INSERT INTO `_robot_talk_copy1` VALUES (218, '지금뭐해]뭐함', '&님은 뭐 하세요?]파티 준비하고 있었어요!');
INSERT INTO `_robot_talk_copy1` VALUES (219, '밥먹었어]밥먹음]점심', '식사 맛있게 하셨어요?]&님, 밥 거르지 마세요!');
INSERT INTO `_robot_talk_copy1` VALUES (220, '고마워]감사]고맙다]땡큐', '감사합니다!]다음에도 잘 부탁드려요!');
INSERT INTO `_robot_talk_copy1` VALUES (221, '혈맹]길드]혈맹가입', '혈맹원 구하시나요?]혈맹 이벤트 있으신가요?');
INSERT INTO `_robot_talk_copy1` VALUES (222, '출석]출첵]체크인', '&님 출첵 완료!]오늘도 접속해주셔서 감사합니다!]좋은 하루 되세요!');
INSERT INTO `_robot_talk_copy1` VALUES (223, '퀘진행]퀘도와줘]퀘스트할래', '퀘스트 같이 하실래요?]&님, 퀘스트 어디까지 하셨어요?]퀘 도움 필요하신가요?]퀘 깨면 보상 뭐예요?');
INSERT INTO `_robot_talk_copy1` VALUES (224, '힐좀]힐주세요]힐필요', '힐 바로 넣을게요!]&님, 피 회복해드릴게요!');
INSERT INTO `_robot_talk_copy1` VALUES (225, '기다려]대기]조금만기다려', '알겠어요, 천천히 오세요!]금방 돌아오시길!');
INSERT INTO `_robot_talk_copy1` VALUES (226, '파티구함]파티할사람]파티원구해요', '파티 금방 모일 거예요!]저도 파티 참여할게요!]&님 파티 초대해주실래요?]몇 명 더 필요하세요?');
INSERT INTO `_robot_talk_copy1` VALUES (227, '안녕]하이', '오늘 기분은 어떠세요?]반가워요!');
INSERT INTO `_robot_talk_copy1` VALUES (228, '물약없어]물약필요]포션없어', '포션 지금 드릴게요!]상점 다녀오실래요?]&님, 물약 같이 사러 가요!]포션 필요하시면 말씀해주세요!');
INSERT INTO `_robot_talk_copy1` VALUES (229, '보스잡자]보스레이드]보스사냥', '보스 언제 뜨나요?]레이드 준비 끝났어요!');
INSERT INTO `_robot_talk_copy1` VALUES (230, '렙업했어]레벨 올림', '더 강해지셨겠네요!]이제 어디서 사냥하실 건가요?');
INSERT INTO `_robot_talk_copy1` VALUES (231, '보스]보스레이드]보스사냥', '보스 언제 뜨나요?]레이드 준비 끝났어요!]보스 잡고 득템하세요!]&님, 레이드 같이 가요!');
INSERT INTO `_robot_talk_copy1` VALUES (232, '사냥가자]사냥하러가자', '지금 사냥 준비됐어요!]어느 사냥터 갈까요?');
INSERT INTO `_robot_talk_copy1` VALUES (233, '혈맹가입]길드모집', '&님 혈맹 가입 환영해요!]길드 분위기 어때요?');
INSERT INTO `_robot_talk_copy1` VALUES (234, '물약없어]물약다씀]포션없어', '포션 지금 드릴게요!]&님, 물약 같이 사러 가요!]포션 필요하시면 말씀해주세요!');
INSERT INTO `_robot_talk_copy1` VALUES (235, '사냥가자]사냥가요', '&님 파티 들어오세요!]물약 충분히 챙기셨나요?');
INSERT INTO `_robot_talk_copy1` VALUES (236, '아이템득]득템]템자랑', '오 득템 축하해요!]&님 운 좋으시네요!]어떤 아이템이신가요?');
INSERT INTO `_robot_talk_copy1` VALUES (237, '힐좀]피없음]힐필요', '힐 바로 넣을게요!]&님, 피 회복해드릴게요!]힐 쿨타임 잠깐만요!');
INSERT INTO `_robot_talk_copy1` VALUES (238, '던전가자]던전출발', '어디 던전 가실래요?]파티 모집하고 출발할까요?]&님이 앞장서주세요!');
INSERT INTO `_robot_talk_copy1` VALUES (239, '대기]조금만기다려', '금방 돌아오시길!]&님 기다리고 있을게요!');
INSERT INTO `_robot_talk_copy1` VALUES (240, '감사]고맙다]땡큐', '감사합니다!]&님 덕분에 클리어했어요!]언제나 고마워요!');
INSERT INTO `_robot_talk_copy1` VALUES (241, 'ㅋㅋ]ㅎㅎ]웃겨', '&님 센스 최고!]오늘 기분 최고네요!');
INSERT INTO `_robot_talk_copy1` VALUES (242, '재접]다시접속]잠깐나감', '재접속 기다릴게요!]&님, 다시 오시면 알려주세요!]문제 없으셨으면 좋겠네요!');
INSERT INTO `_robot_talk_copy1` VALUES (243, '거래하자]거래가능]거래할래', '거래창 열었어요!]안전거래로 진행할까요?');
INSERT INTO `_robot_talk_copy1` VALUES (244, '못하네]한심]실망', '실력 탓 그만]본인 실력부터 점검');
INSERT INTO `_robot_talk_copy1` VALUES (245, 'ㅅㅂ]시바]ㅄ]씹', '뭐 씨발?]매너좀요]&님 인성 조졌네');
