INSERT INTO `_robot_talk_copy1` VALUES (256, 'ok]OK', '알았으니 그만]그래서 어쩌라고]응~ 너한테 관심없음');
INSERT INTO `_robot_talk_copy1` VALUES (257, '유저신고]고소', '운영자도 바쁨]규칙이나 지켜라]블럭한다고 달라질 게 있나');
INSERT INTO `_robot_talk_copy1` VALUES (258, 'ㅅㅂ]시발]ㅄ', '욕은 니한테 반사]또 욕이네]매너좀요]&님 인성 조졌네');
INSERT INTO `_robot_talk_copy1` VALUES (259, '뭐함]왜이래', '내가 뭘?]할 일이나 하셈');
