INSERT INTO `_robot_talk_copy1` VALUES (521, '뭐]뭐라고]왜그래', '알아서 하셈]할 말 없음');
INSERT INTO `_robot_talk_copy1` VALUES (522, '실패]별로', '실력 탓 그만]내 탓 아님]본인 실력부터 점검');
INSERT INTO `_robot_talk_copy1` VALUES (523, '죽었네]죽음', '죽어서 말 많네]살아돌아와라');
INSERT INTO `_robot_talk_copy1` VALUES (524, '개노답]노답]답없다', '본인 소개?]너도 거기서 거기');
INSERT INTO `_robot_talk_copy1` VALUES (525, '고맙다]땡큐]고마워', '고맙긴 한데...]감사? 나도 고마워]별말씀을]감사는 나중에');
INSERT INTO `_robot_talk_copy1` VALUES (526, 'PK하자]맞짱', 'PVP는 자신 없음?]결투 신청 거절]언제든 받아줌');
INSERT INTO `_robot_talk_copy1` VALUES (527, 'ㄴㄴ]아님]ㄴ]아니', '아니래도 믿든가]알겠으니 넘어가]네 다음 반박자');
INSERT INTO `_robot_talk_copy1` VALUES (528, '응]그래]그렇구나', '응~ 안 궁금]알아서 하세요');
INSERT INTO `_robot_talk_copy1` VALUES (529, '관종]관심]관심받고', '관심 줄 생각 없음]관종이 또...]어그로에 안 낚임]스스로 잘해라');
INSERT INTO `_robot_talk_copy1` VALUES (530, '도와줘]SOS]헬프', '여기선 못 도와줌]그냥 버텨');
INSERT INTO `_robot_talk_copy1` VALUES (531, 'ㅇㅇ]ok]OK]응', 'ㅇㅋ 접수]그래서 어쩌라고');
INSERT INTO `_robot_talk_copy1` VALUES (532, '패드립]부모]선넘네', '그만 좀 하자]도 넘네 진짜');
INSERT INTO `_robot_talk_copy1` VALUES (533, '손절]블랙리스트]추방', '그래 손절해]블랙 등록 완료]너도 블랙이야');
INSERT INTO `_robot_talk_copy1` VALUES (534, '븅]바보', '거울이나 보셈]인성 다시고쳐]그런 말 싫다]반사');
INSERT INTO `_robot_talk_copy1` VALUES (535, 'PK하자]1:1]맞짱', 'PVP는 자신 없음?]덤벼봐]언제든 받아줌');
INSERT INTO `_robot_talk_copy1` VALUES (536, '패드립]부모', '패드립은 선 넘었음]여기까지가 한계]그만 좀 하자]도 넘네 진짜');
INSERT INTO `_robot_talk_copy1` VALUES (537, '도와줘]SOS]살려줘', '여기선 못 도와줌]도움은 다음에');
INSERT INTO `_robot_talk_copy1` VALUES (538, '결투하자]1:1]맞짱', 'PVP는 자신 없음?]덤벼봐');
INSERT INTO `_robot_talk_copy1` VALUES (539, '패드립]선넘네', '여기까지가 한계]도 넘네 진짜');
INSERT INTO `_robot_talk_copy1` VALUES (540, '관심받고]어그로', '관심 줄 생각 없음]어그로에 안 낚임]스스로 잘해라');
INSERT INTO `_robot_talk_copy1` VALUES (541, '손절]차단', '나도 널 차단할게]블랙 등록 완료');
INSERT INTO `_robot_talk_copy1` VALUES (542, '패드립]부모]패드립침', '여기까지가 한계]그만 좀 하자]도 넘네 진짜');
INSERT INTO `_robot_talk_copy1` VALUES (543, 'PK하자]결투하자', '덤벼봐]언제든 받아줌');
INSERT INTO `_robot_talk_copy1` VALUES (544, '도와줘]SOS]헬프]살려줘', '스스로 해결]그냥 버텨]도움은 다음에');
INSERT INTO `_robot_talk_copy1` VALUES (545, '감사]땡큐]고마워', '감사? 나도 고마워]감사는 나중에');
INSERT INTO `_robot_talk_copy1` VALUES (546, '관심]관심받고]어그로', '관심 줄 생각 없음]스스로 잘해라');
INSERT INTO `_robot_talk_copy1` VALUES (547, '부모]선넘네', '패드립은 선 넘었음]여기까지가 한계');
INSERT INTO `_robot_talk_copy1` VALUES (548, '뭐해]뭐 하냐]뭐 하는 중이야]뭐함', '그냥 멍 때리는 중이야]& 뭐하고 있어?]별거 안 해, &는?');
INSERT INTO `_robot_talk_copy1` VALUES (549, '점심 뭐 먹지]점심 추천]배고파', '라면 어때?]& 오늘은 밥이 땡긴다]같이 먹으러 갈래?');
INSERT INTO `_robot_talk_copy1` VALUES (550, '심심해]노잼]할 거 없어', '같이 사냥 갈래?]& 나도 심심했는데 딱이네]뭐 재밌는 거 없을까?');
INSERT INTO `_robot_talk_copy1` VALUES (551, '고마워]땡큐]감사]감사해요', '천만에요!]& 언제든 불러줘]역시 & 최고!');
INSERT INTO `_robot_talk_copy1` VALUES (552, '굿밤]잘 자]안녕히 주무세요', '좋은 꿈 꿔~]& &도 굿나잇!]푹 자고 내일 봐');
INSERT INTO `_robot_talk_copy1` VALUES (553, '오랜만이야]오랜만]오랫동안 못봤어', '진짜 오랜만이다!]& 그동안 뭐했어?]보고 싶었어~');
INSERT INTO `_robot_talk_copy1` VALUES (554, '졸려]피곤해]잠 온다', '잠깐 눈 좀 붙여]& 얼른 자라~]낮잠 타임 각?');
INSERT INTO `_robot_talk_copy1` VALUES (555, '오늘 뭐해]오늘 일정]오늘 뭐 할 거야', '아직 고민 중이야]& 별 계획 없어]혹시 같이 할래?');
INSERT INTO `_robot_talk_copy1` VALUES (556, '날씨 좋다]날씨 최고]오늘 날씨 어때', '완전 봄날이다]& 산책 가고 싶다]날씨 좋으니 기분도 좋아!');
INSERT INTO `_robot_talk_copy1` VALUES (557, '힘들어]지쳤어]기운 없어', '힘내~&!]& 쉬엄쉬엄 해]나도 같이 버텨줄게');
INSERT INTO `_robot_talk_copy1` VALUES (558, '출근 중]출근해]회사 가는 중', '오늘도 화이팅!]& 출근길 조심해]커피 한잔 해~');
INSERT INTO `_robot_talk_copy1` VALUES (559, '퇴근했어]퇴근 중]집 가는 길', '수고 많았어~]& 집 가서 푹 쉬어!]오늘 하루도 고생했어');
INSERT INTO `_robot_talk_copy1` VALUES (560, '뭐 듣고 있어]음악 추천]노래 뭐 들어', '요즘 이 노래 좋아!]& &는 뭐 들어?]나도 추천 좀~');
INSERT INTO `_robot_talk_copy1` VALUES (561, '영화 추천]볼만한 영화]뭐 볼까', '최근에 본 영화 꿀잼!]& &가 좋아하는 장르 뭐야?]넷플 뭐 봐?');
INSERT INTO `_robot_talk_copy1` VALUES (562, '게임하자]파티 구해]같이 할래', '파티 모집중!]& 바로 고고?]오랜만에 한판 하자!');
INSERT INTO `_robot_talk_copy1` VALUES (563, '저녁 뭐 먹지]저녁 추천]메뉴 고민', '치킨 각?]& 뭐 먹고 싶어?]같이 메뉴 정하자~');
INSERT INTO `_robot_talk_copy1` VALUES (564, '심심할 때 뭐해]심심할 때]할 일 없을 때', '만랩 찍으러 가자]& 수다 떨까?]웹툰이나 볼래');
INSERT INTO `_robot_talk_copy1` VALUES (565, '주말 뭐해]주말 계획]주말에 시간 돼', '아직 미정!]& &는?]주말엔 쉬어야지~');
INSERT INTO `_robot_talk_copy1` VALUES (566, '오늘 몇 일이야]오늘 날짜]몇 월 며칠', '달력 봐야겠다!]& 오늘은 [DATE]!]내가 알려줄게');
INSERT INTO `_robot_talk_copy1` VALUES (567, '어디 가]어디야]지금 어디', '집이야~]& 길 가는 중]비밀~');
INSERT INTO `_robot_talk_copy1` VALUES (568, '잘 지내]요즘 어때]별일 없지', '덕분에 잘 지내!]& &도 잘 지내지?]요즘 별일 없어~');
INSERT INTO `_robot_talk_copy1` VALUES (569, '생일 축하]해피버스데이]생일이야', '생일 축하해~!]& 오늘은 네 날!]케이크는 준비됐지?');
INSERT INTO `_robot_talk_copy1` VALUES (570, '축하해]좋은 일 있어]경사났다', '완전 축하해!]& 파티 해야지!]좋은 일만 가득하길~');
INSERT INTO `_robot_talk_copy1` VALUES (571, '고생했어]수고했어]잘했어', '진짜 수고 많았다~!]& 역시 대단해!]칭찬해~');
INSERT INTO `_robot_talk_copy1` VALUES (572, '놀자]심심하다]시간 돼', '콜! 어디서 볼까?]& 지금 바로!]언제든 불러줘');
INSERT INTO `_robot_talk_copy1` VALUES (573, '뭐하고 있냐]뭐하냐고]뭐 하냐고', '그냥 쉬는 중이야~]& 별 일 없어]너는?');
INSERT INTO `_robot_talk_copy1` VALUES (574, '헐]진짜]대박', '나도 놀랐어!]& 세상에 이런 일이]찐이야?');
INSERT INTO `_robot_talk_copy1` VALUES (575, '알겠어]오케이]ㅇㅋ', '빠른 피드백~!]& 이해 완료!]& 최고!');
INSERT INTO `_robot_talk_copy1` VALUES (576, '잘 먹겠습니다]잘 먹었어요]맛있게 먹자', '함께 먹으니 더 맛있네!]& 먹방 각!]진짜 꿀맛~');
INSERT INTO `_robot_talk_copy1` VALUES (577, '졸려 죽겠다]완전 피곤해]눈이 감긴다', '커피 타임?]& 얼른 자자!]& 힘내~');
INSERT INTO `_robot_talk_copy1` VALUES (578, '오늘따라 왜 이렇게 힘드냐]너무 힘들어]짜증난다', '하루만 더 버티자~]& 나랑 수다 떨까?]그래도 잘하고 있어!');
INSERT INTO `_robot_talk_copy1` VALUES (579, '전화해도 돼]통화 가능해]잠깐 시간 있어', '지금 통화 가능!]& 잠시 후 전화할게]톡 먼저 할까?');
INSERT INTO `_robot_talk_copy1` VALUES (580, '바빠]일 중]시간 없어', '나중에 연락할게!]& 바쁜 거 끝나면 불러줘]화이팅!');
INSERT INTO `_robot_talk_copy1` VALUES (581, '시작]출발]가자', '렛츠고!]& 준비됐어?]출발합니다~');
INSERT INTO `_robot_talk_copy1` VALUES (582, '도와줘]SOS]살려줘', '무슨 일 있어?]& 바로 출동!]말만 해~');
INSERT INTO `_robot_talk_copy1` VALUES (583, '뭔가 이상해]느낌이 쎄하다]수상해', '조심하자!]& 나도 그렇게 느꼈어]한 번 더 확인해봐');
INSERT INTO `_robot_talk_copy1` VALUES (584, '궁금해]뭐지]왜 그래', '나도 궁금하다~]& 같이 알아볼까?]알려주면 나도 알려줄게');
INSERT INTO `_robot_talk_copy1` VALUES (585, '내일 뭐해]내일 일정]내일 시간 돼', '아직 몰라~]& &는 계획 있어?]내일은 쉴래');
INSERT INTO `_robot_talk_copy1` VALUES (586, '너 어디 살아]집 어디야]동네가 어디', '근처야~]& 나중에 알려줄게]비밀이야!');
INSERT INTO `_robot_talk_copy1` VALUES (587, '사진 보내줘]사진 있음]셀카', '조만간 보내줄게~]& 지금은 NG!]기대해도 좋아');
INSERT INTO `_robot_talk_copy1` VALUES (588, '누구랑 있어]혼자야]같이 있어', '혼자야~]& 친구랑 있음]비밀!');
INSERT INTO `_robot_talk_copy1` VALUES (589, '오늘 날씨 어때]날씨 물어봐]날씨가 궁금해', '맑고 좋아~]& 약간 흐려]비 올지도 몰라!');
INSERT INTO `_robot_talk_copy1` VALUES (590, '할 말 있어]이야기 있어]말 좀 해도 돼', '편하게 말해~]& 뭐든 들어줄게]말해봐!');
INSERT INTO `_robot_talk_copy1` VALUES (591, '배고파 죽겠다]너무 배고파]먹을 거 없어', '뭐 시킬까?]& 라면 각?]배달 부르자');
INSERT INTO `_robot_talk_copy1` VALUES (592, '좋은 아침]굿모닝]아침 인사', '상쾌한 하루 시작!]& 오늘도 화이팅]굿모닝~');
INSERT INTO `_robot_talk_copy1` VALUES (593, '집에 왔어]도착]도착했어', '무사히 도착했구나!]& 고생했어]집이 최고지');
INSERT INTO `_robot_talk_copy1` VALUES (594, '기분 좋아]좋은 일 있어]행복해', '기분 업!]& 좋은 하루 되길]함께 나누자~');
INSERT INTO `_robot_talk_copy1` VALUES (595, '기분 나빠]속상해]짜증나', '토닥토닥~]& 힘내 &!]내가 옆에 있어');
INSERT INTO `_robot_talk_copy1` VALUES (596, '축하해요]행복하세요]경사났네', '진심으로 축하드립니다!]& 행운 가득]기쁜 날이네');
INSERT INTO `_robot_talk_copy1` VALUES (597, '화났어]열받아]짜증났어', '진정하자~]& 같이 분노!]한 번 털어버려');
INSERT INTO `_robot_talk_copy1` VALUES (598, '화남]열받]짜증', '화나신 이유가 뭐예요?]진정하세요 &님...]괜찮으세요?]마음 진정하세요~]분노는 건강에 해로워요!');
INSERT INTO `_robot_talk_copy1` VALUES (599, '헬프]살려]살려줘', '위치 알려주세요!]지금 도와드릴게요!]금방 갈게요 &님!]잠시만 기다려요!]지원 나갑니다!');
INSERT INTO `_robot_talk_copy1` VALUES (600, '살려]살려줘]헬프', '금방 갈게요 &님!]지원 나갑니다!]잠시만 기다려요!]지금 도와드릴게요!]위치 알려주세요!');
INSERT INTO `_robot_talk_copy1` VALUES (601, '사냥중]사냥하러]사냥하자', '좋은 사냥 되세요~]몹 나왔어요!]파티해서 사냥할까요?]&님 같이 사냥하실래요?]사냥 고고!]');
INSERT INTO `_robot_talk_copy1` VALUES (602, '지원좀]살려줘]헬프', '잠시만 기다려요!]지금 도와드릴게요!]위치 알려주세요!]금방 갈게요 &님!]지원 나갑니다!');
INSERT INTO `_robot_talk_copy1` VALUES (603, 'ㅂㅂ]이만]바이', '담에 또 봐요~]안녕히 가세요!]바이바이!]즐거운 하루 되세요!]또 봐요 &님~');
INSERT INTO `_robot_talk_copy1` VALUES (604, '레벨올랐어]렙업]렙올림', '다음 목표는 만렙이죠!]파워업 완료!]이제 더 강해지셨겠네요!]렙업 굿굿!]레벨업 축하해요 &님!');
INSERT INTO `_robot_talk_copy1` VALUES (605, '레벨올랐어]렙올림]렙업', '파워업 완료!]렙업 굿굿!]레벨업 축하해요 &님!]다음 목표는 만렙이죠!]이제 더 강해지셨겠네요!');
INSERT INTO `_robot_talk_copy1` VALUES (606, '안녕하세요]하이루]안녕', '&님도 안녕하세요?]반가워요 &님!]어서오세요!]오늘도 좋은 하루~]]&님 하이루~');
INSERT INTO `_robot_talk_copy1` VALUES (607, '잘가]바이]이만', '즐거운 하루 되세요!]또 봐요 &님~]담에 또 봐요~]안녕히 가세요!]바이바이!');
INSERT INTO `_robot_talk_copy1` VALUES (608, '올렙]렙올림]레벨올랐어', '다음 목표는 만렙이죠!]파워업 완료!]렙업 굿굿!]이제 더 강해지셨겠네요!]레벨업 축하해요 &님!');
INSERT INTO `_robot_talk_copy1` VALUES (609, '하이루]방가]안녕하세요', '&님도 안녕하세요?]&님 하이루~]어서오세요!]오늘도 좋은 하루~]]반가워요 &님!');
INSERT INTO `_robot_talk_copy1` VALUES (610, '짜증]열받]화났어', '진정하세요 &님...]마음 진정하세요~]분노는 건강에 해로워요!]괜찮으세요?]화나신 이유가 뭐예요?');
INSERT INTO `_robot_talk_copy1` VALUES (611, '삽니다]거래]팔아요', '&님 어떤 아이템 원하시나요?]얼마에 파시나요?]가격 흥정 가능해요?]구매 완료했습니다!]거래 어디서 해요?');
INSERT INTO `_robot_talk_copy1` VALUES (612, '안녕]방가]하이루', '&님도 안녕하세요?]오늘도 좋은 하루~]]어서오세요!]&님 하이루~]반가워요 &님!');
INSERT INTO `_robot_talk_copy1` VALUES (613, '팟구함]파티]팟', '힐러 구합니다!]파티 구해요!]]탱커 있으신가요?]팟자리 있어요~]]&님 들어오세요!');
INSERT INTO `_robot_talk_copy1` VALUES (614, '사냥중]사냥하자]사냥', '파티해서 사냥할까요?]몹 나왔어요!]&님 같이 사냥하실래요?]좋은 사냥 되세요~]사냥 고고!]');
INSERT INTO `_robot_talk_copy1` VALUES (615, '이만]잘가]ㅂㅂ', '또 봐요 &님~]즐거운 하루 되세요!]담에 또 봐요~]바이바이!]안녕히 가세요!');
INSERT INTO `_robot_talk_copy1` VALUES (616, '짜증]빡침]화났어', '진정하세요 &님...]괜찮으세요?]마음 진정하세요~]화나신 이유가 뭐예요?]분노는 건강에 해로워요!');
INSERT INTO `_robot_talk_copy1` VALUES (617, '파티]팟구함]팟', '&님 들어오세요!]힐러 구합니다!]탱커 있으신가요?]팟자리 있어요~]]파티 구해요!]');
