INSERT INTO `_robot_talk_copy1` VALUES (818, '사냥하러]몹]사냥하자', '파티해서 사냥할까요?]사냥 고고!]]몹 나왔어요!]&님 같이 사냥하실래요?]좋은 사냥 되세요~');
INSERT INTO `_robot_talk_copy1` VALUES (819, '파티]팟좀]팟구함', '&님 들어오세요!]탱커 있으신가요?]파티 구해요!]]힐러 구합니다!]팟자리 있어요~]');
INSERT INTO `_robot_talk_copy1` VALUES (820, '올렙]레벨업]렙업', '렙업 굿굿!]파워업 완료!]다음 목표는 만렙이죠!]레벨업 축하해요 &님!]이제 더 강해지셨겠네요!');
INSERT INTO `_robot_talk_copy1` VALUES (821, '화남]화났어]짜증', '괜찮으세요?]화나신 이유가 뭐예요?]진정하세요 &님...]분노는 건강에 해로워요!]마음 진정하세요~');
INSERT INTO `_robot_talk_copy1` VALUES (822, '사냥하자]사냥중]사냥', '좋은 사냥 되세요~]몹 나왔어요!]&님 같이 사냥하실래요?]사냥 고고!]]파티해서 사냥할까요?');
INSERT INTO `_robot_talk_copy1` VALUES (823, '훌륭해]굿]멋져', '칭찬합니다!]완전 프로시네요~]멋지십니다!]역시 &님 최고!]굿굿');
