INSERT INTO `_robot_talk_copy1` VALUES (955, '안녕히]ㅂㅂ]이만', '바이바이!]담에 또 봐요~]또 봐요 &님~]즐거운 하루 되세요!]안녕히 가세요!');
INSERT INTO `_robot_talk_copy1` VALUES (956, '훌륭해]짱]잘했어', '칭찬합니다!]역시 &님 최고!]멋지십니다!]완전 프로시네요~]굿굿');
INSERT INTO `_robot_talk_copy1` VALUES (957, '거래]삽니다]구매', '&님 어떤 아이템 원하시나요?]가격 흥정 가능해요?]구매 완료했습니다!]거래 어디서 해요?]얼마에 파시나요?');
INSERT INTO `_robot_talk_copy1` VALUES (958, '사냥중]사냥]몹', '몹 나왔어요!]파티해서 사냥할까요?]&님 같이 사냥하실래요?]좋은 사냥 되세요~]사냥 고고!]');
INSERT INTO `_robot_talk_copy1` VALUES (959, '레벨올랐어]렙올림]레벨업', '레벨업 축하해요 &님!]이제 더 강해지셨겠네요!]다음 목표는 만렙이죠!]렙업 굿굿!]파워업 완료!');
INSERT INTO `_robot_talk_copy1` VALUES (960, '구매]삽니다]팔아요', '가격 흥정 가능해요?]얼마에 파시나요?]&님 어떤 아이템 원하시나요?]구매 완료했습니다!]거래 어디서 해요?');
INSERT INTO `_robot_talk_copy1` VALUES (961, '헬프]살려]지원좀', '지금 도와드릴게요!]지원 나갑니다!]잠시만 기다려요!]위치 알려주세요!]금방 갈게요 &님!');
INSERT INTO `_robot_talk_copy1` VALUES (962, '짜증]화남]화났어', '괜찮으세요?]분노는 건강에 해로워요!]화나신 이유가 뭐예요?]마음 진정하세요~]진정하세요 &님...');
