INSERT INTO `_robot_talk_copy1` VALUES (1022, '열받]화났어]짜증', '진정하세요 &님...]마음 진정하세요~]괜찮으세요?]분노는 건강에 해로워요!]화나신 이유가 뭐예요?');
INSERT INTO `_robot_talk_copy1` VALUES (1023, '팔아요]구매]팔겠습니다', '&님 어떤 아이템 원하시나요?]거래 어디서 해요?]구매 완료했습니다!]가격 흥정 가능해요?]얼마에 파시나요?');
INSERT INTO `_robot_talk_copy1` VALUES (1024, '렙업]올렙]레벨업', '렙업 굿굿!]이제 더 강해지셨겠네요!]다음 목표는 만렙이죠!]파워업 완료!]레벨업 축하해요 &님!');
INSERT INTO `_robot_talk_copy1` VALUES (1025, '사냥]몹]사냥하러', '몹 나왔어요!]파티해서 사냥할까요?]&님 같이 사냥하실래요?]사냥 고고!]]좋은 사냥 되세요~');
INSERT INTO `_robot_talk_copy1` VALUES (1026, '파티모집]팟구함]팟좀', '탱커 있으신가요?]힐러 구합니다!]팟자리 있어요~]]파티 구해요!]]&님 들어오세요!');
INSERT INTO `_robot_talk_copy1` VALUES (1027, '안녕히]잘가]ㅂㅂ', '즐거운 하루 되세요!]안녕히 가세요!]바이바이!]담에 또 봐요~]또 봐요 &님~');
