INSERT INTO `_robot_talk_copy1` VALUES (1456, '저기요', 'ㅇㅇ?] 왜요?, 저요?');
INSERT INTO `_robot_talk_copy1` VALUES (1457, '잘지]잘있었]안녕하셨', '&님도 잘 지냈어요?] &님 덕분에 잘 지냈어요.]아니요ㅠㅠ 러쉬하다 망했어요.');
INSERT INTO `_robot_talk_copy1` VALUES (1458, '못지냈]별로 못]', '그렇구나, 힘내세요!]이제 부터 잘 지내면 돼죠!');
INSERT INTO `_robot_talk_copy1` VALUES (1459, '밥은]밥먹', '저는 먹었어요.]&님은 식사 하셨어요?]&프로 식사는 잡쉈어?]아니요. 집에 쌀이 떨어졌어요 ㅠㅠ]이제 먹을거에요.');
INSERT INTO `_robot_talk_copy1` VALUES (1460, '안녕]하이]방가]ㅎㅇ', '&님도 안녕하세요.]안녕하세요.]방가방가]하이루]');
INSERT INTO `_robot_talk_copy1` VALUES (1461, '즐겜]즐린]', '&님도 즐겜 하세요.]네 즐린 하세요.]네 감사합니다.]&님도 즐린 되세요.');
INSERT INTO `_robot_talk_copy1` VALUES (1462, '잘있어]ㅂ2]ㅂㅂ', '&님 들어가세요.]잘가요]ㅂㅂ2');
INSERT INTO `_robot_talk_copy1` VALUES (1463, '잘자', '&님도 잘자요.]저는 밤샘 할거라 ㅎ]안녕히주무세요!');
INSERT INTO `_robot_talk_copy1` VALUES (1464, '어디가요]어디감]', '사냥가요!]레이드 ㄱㄱ]돈벌러가요]렙업 하러가요');
INSERT INTO `_robot_talk_copy1` VALUES (1465, '죽었]죽으', 'ㅅㅂ놀리냐]안끄지냐]ㅡㅡㅋ]ㅠㅠ]부활좀]살려주세요ㅠ');
INSERT INTO `_robot_talk_copy1` VALUES (1466, '사랑해]샤랑', '저두 사랑해요!]ㅡㅡㅋ]뭐라구요??');
INSERT INTO `_robot_talk_copy1` VALUES (1467, '템좀', '꺼져 그지야]저도 그지라서..]저도 초보라..]');
INSERT INTO `_robot_talk_copy1` VALUES (1468, '득템하세', '&님도 득템요]&님도 득템 하세요.]감사합니다.]우리 모두 득템 해요!');
INSERT INTO `_robot_talk_copy1` VALUES (1469, '득템했어]득템하셨]템좀드', '아니요]그지에요]데이 한장 먹었어요.]어제 투망 먹음 ㅎㅎ]어제 잊섬가서 고줌 하나 먹었어요.]오피 먹었어요ㅎ');
INSERT INTO `_robot_talk_copy1` VALUES (1470, '이쁘다]예뻐]예쁘네', '&님 사람 볼줄 아시네요!]이쁜건 알아가지고ㅋ]꼴에 이쁜건 알아서ㅡㅡ]뭐 꺼져!');
INSERT INTO `_robot_talk_copy1` VALUES (1471, '먹자하지마]먹지마', '&님 제껀데 왜요?]싫은데~]먹을건데ㅋㅋ &님 부들부들?');
INSERT INTO `_robot_talk_copy1` VALUES (1472, '잘생겼]잘생기]잘생김', '저도 알아요 ㅎ]&님도 멋져요!]감사합니다^^]^^;');
