-- ----------------------------
-- Table structure for _robot_shop
-- ----------------------------
DROP TABLE IF EXISTS `_robot_shop`;
CREATE TABLE `_robot_shop`  (
  `name` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '로봇 이름',
  `item` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '아이템 이름',
  `en` tinyint(3) NOT NULL DEFAULT 0 COMMENT '아이템 인첸트',
  `bress` tinyint(3) NOT NULL DEFAULT 0 COMMENT '아이템 상태',
  `count` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '아이템 갯수',
  `definite` tinyint(3) NOT NULL DEFAULT 1 COMMENT '확인된 상태인지',
  `buy` enum('true','false') CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'true' COMMENT '매수 여부',
  `sell` enum('true','false') CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'true' COMMENT '매도 여부',
  `ment` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '상품에 대한 홍보 문구',
  `response` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '동일한 가격에 아이템이 존재할때\r\n어떤아이템을 구입할것인지 모호할때\r\n해당 칼럼에 값을 참고해서 찾게됨.\r\n\r\n- 작성방법 (판매하는 물건이 \'싸울아비 장검\')\r\n싸울,싸울아비,장검',
  PRIMARY KEY (`name`, `item`, `en`, `bress`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of _robot_shop
-- ----------------------------

