-- ----------------------------
-- Table structure for monster
-- ----------------------------
DROP TABLE IF EXISTS `monster`;
CREATE TABLE `monster`  (
  `name` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `name_id` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `gfx` int(10) NOT NULL DEFAULT 0,
  `gfx_mode` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `boss` enum('true','false') CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'false',
  `boss_class` enum('최상급 보스','상급 보스','중급 보스','하급 보스','일반 몬스터') CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '일반 몬스터',
  `level` tinyint(3) UNSIGNED NOT NULL DEFAULT 0,
  `hp` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `mp` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `tic_hp` int(10) NOT NULL DEFAULT 0,
  `tic_mp` int(10) NOT NULL DEFAULT 0,
  `str` int(10) NOT NULL DEFAULT 0,
  `dex` int(10) NOT NULL DEFAULT 0,
  `con` int(10) NOT NULL DEFAULT 0,
  `int` int(10) NOT NULL DEFAULT 0,
  `wis` int(10) NOT NULL DEFAULT 0,
  `cha` int(10) NOT NULL DEFAULT 0,
  `mr` tinyint(3) UNSIGNED NOT NULL DEFAULT 0,
  `ac` tinyint(3) UNSIGNED NOT NULL DEFAULT 0,
  `exp` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `lawful` int(10) NOT NULL DEFAULT 0,
  `size` enum('small','large','big') CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'small',
  `family` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `atk_type` tinyint(3) UNSIGNED NOT NULL DEFAULT 0,
  `atk_range` tinyint(3) UNSIGNED NOT NULL DEFAULT 1,
  `atk_invis` enum('true','false') CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'false',
  `atk_poly` enum('true','false') CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'false',
  `is_pickup` enum('true','false') CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'false',
  `is_revival` enum('true','false') CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'false',
  `is_toughskin` enum('true','false') CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'false',
  `is_adendrop` enum('true','false') CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'true',
  `is_taming` enum('true','false') CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'true',
  `is_undead` enum('true','false') CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'false',
  `is_turn_undead` enum('false','true') CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `resistance_earth` tinyint(3) NOT NULL DEFAULT 0,
  `resistance_fire` tinyint(3) NOT NULL DEFAULT 0,
  `resistance_wind` tinyint(3) NOT NULL DEFAULT 0,
  `resistance_water` tinyint(3) NOT NULL DEFAULT 0,
  `arrowGfx` int(10) NOT NULL DEFAULT 0,
  `msg_atk` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `msg_die` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `msg_spawn` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `msg_escape` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `msg_walk` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `haste` enum('true','false') CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'false',
  `bravery` enum('true','false') CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'false',
  `faust_monster` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `chance` int(10) NOT NULL DEFAULT 0,
  `effect` int(10) NOT NULL DEFAULT 0,
  `karma` int(10) NOT NULL DEFAULT 0 COMMENT '야히는 음수\r\n발록은 양후\r\nex) -10 은 야히우호도 10이라는 의미\r\nex) 200은 발록 우호도 20',
  PRIMARY KEY (`name`) USING BTREE,
  INDEX `name`(`name`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

