  `pet_id` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `letter_id` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `구분1` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `구분2` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `type` tinyint(3) UNSIGNED NOT NULL,
  `gfxid` int(2) NOT NULL DEFAULT 0,
  `count` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `quantity` tinyint(3) UNSIGNED NOT NULL DEFAULT 0,
  `en` tinyint(3) NOT NULL DEFAULT 0,
  `definite` tinyint(3) UNSIGNED NOT NULL DEFAULT 0,
  `bress` tinyint(3) NOT NULL DEFAULT 0,
  `durability` tinyint(3) UNSIGNED NOT NULL DEFAULT 0,
  `time` int(10) NOT NULL,
  `web_price_s` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `web_price_d` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `web_insert_date` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `web_end_date` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `web_is_sell` tinyint(3) UNSIGNED NOT NULL DEFAULT 0,
  `web_note` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  PRIMARY KEY (`uid`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

