-- ----------------------------
-- Procedure structure for deleteData
-- ----------------------------
DROP PROCEDURE IF EXISTS `deleteData`;
delimiter ;;
CREATE PROCEDURE `deleteData`(cnt INTEGER)
BEGIN
  DECLARE done INT DEFAULT 0;
  DECLARE cName,cCName,clogin VARCHAR(45);
  DECLARE cRank,cID,cObj INT;
  DECLARE num INT DEFAULT 0;
  DECLARE cur1 CURSOR FOR SELECT * FROM (select char_name,ClanRank ,clanid,objid,clanname,login
from accounts acc
left join characters cha on acc.login = cha.account_name
where DATEDIFF(now(),lastactive) > cnt
) A;
DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' SET done = 1;

  OPEN cur1;
  REPEAT
    FETCH cur1 INTO cName, cRank, cID,cObj,cCName,clogin;

    IF NOT done THEN

	IF cRank = 4 THEN
		update characters set ClanID=0,Clanname='',ClanRank=0 where ClanID = cID;
		DELETE FROM clan_warehouse WHERE clan_name = cCName;
		DELETE FROM clan_data WHERE leader_id =cID;
	END IF;

		DELETE FROM letter WHERE receiver = cName;
		DELETE FROM character_buddys WHERE char_id  = cObj;
		DELETE FROM character_buff WHERE char_obj_id = cObj;
		DELETE FROM character_config WHERE object_id = cObj;
		DELETE FROM character_items WHERE char_id = cObj;
		DELETE FROM character_quests WHERE char_id = cObj;
		DELETE FROM character_skills WHERE char_obj_id = cObj;
		DELETE FROM character_teleport WHERE char_id = cObj;
		DELETE FROM character_soldier WHERE char_id = cObj;
		DELETE FROM characters WHERE char_name= cName;

		set num = (select count(*) as cnt  from characters where account_name = clogin);
		if num = 0 then
			DELETE FROM character_warehouse WHERE account_name = clogin;
			DELETE FROM character_elf_warehouse WHERE account_name = clogin;
 			DELETE FROM character_package_warehouse WHERE account_name = clogin;
 			DELETE FROM accounts WHERE login =	clogin;
		END IF;

    END IF;
  UNTIL done END REPEAT;
CLOSE cur1;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for DELETE_DEATH_PENALTY_24_HOUR
-- ----------------------------
DROP PROCEDURE IF EXISTS `DELETE_DEATH_PENALTY_24_HOUR`;
delimiter ;;
CREATE PROCEDURE `DELETE_DEATH_PENALTY_24_HOUR`()
BEGIN
	DELETE FROM character_death_exp WHERE durationTime <= NOW();
	DELETE FROM character_death_item WHERE durationTime <= NOW();
END
;;
delimiter ;

